const response = $input.first().json;
const runs = response.workflow_runs || [];

const now = new Date();
const kstFormatter = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Seoul',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
});
const todayKst = kstFormatter.format(now);

// KRX 공식 휴장일 (trading_days.json 동기화)
const krxHolidays = new Set([
  '2026-01-01', '2026-02-16', '2026-02-17', '2026-02-18', '2026-03-02',
  '2026-05-01', '2026-05-05', '2026-05-25', '2026-06-03', '2026-08-17',
  '2026-09-24', '2026-09-25', '2026-10-05', '2026-10-09', '2026-12-25',
  '2026-12-31', '2027-01-01', '2027-02-05', '2027-02-08', '2027-02-09',
  '2027-03-01', '2027-05-05', '2027-05-13', '2027-08-16', '2027-09-14',
  '2027-09-15', '2027-09-16', '2027-10-04', '2027-12-25', '2027-12-31'
]);

const dayOfWeek = now.getDay();
const isWeekend = dayOfWeek === 0 || dayOfWeek === 6;
const isHoliday = krxHolidays.has(todayKst) || isWeekend;

if (isHoliday) {
  return [{
    json: {
      todayKst,
      alreadySucceededToday: true,
      isRunningNow: false,
      shouldTrigger: false,
      reason: `Today (${todayKst}) is a designated KRX market holiday/weekend. Clean exit without trigger.`
    }
  }];
}

let alreadySucceededToday = false;
let lastSuccessTimeKst = null;

for (const r of runs) {
  if (r.status === 'completed' && r.conclusion === 'success') {
    const runDateKst = kstFormatter.format(new Date(r.created_at));
    if (runDateKst === todayKst) {
      const durationMs = new Date(r.updated_at).getTime() - new Date(r.run_started_at || r.created_at).getTime();
      if (durationMs > 45000) {
        alreadySucceededToday = true;
        lastSuccessTimeKst = r.created_at;
        break;
      }
    }
  }
}

const isRunningNow = runs.some(r => r.status === 'in_progress' || r.status === 'queued');
const shouldTrigger = !alreadySucceededToday && !isRunningNow;
const reason = alreadySucceededToday 
  ? `Already succeeded today (${todayKst}) at ${lastSuccessTimeKst}`
  : (isRunningNow ? 'Workflow is currently in progress / queued' : `Ready to trigger refresh for ${todayKst}`);

return [{
  json: {
    todayKst,
    alreadySucceededToday,
    isRunningNow,
    shouldTrigger,
    reason
  }
}];
